import{_ as i,o,c as s,a2 as a,j as e,a as n}from"./chunks/framework.CRkDNIZq.js";const m=JSON.parse('{"title":"Technical Interview Questions & Answers (150+ Questions)","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),r={name:"09-interview-qa.md"};function d(c,t,h,l,u,p){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="technical-interview-questions-answers-150-questions" tabindex="-1">Technical Interview Questions &amp; Answers (150+ Questions) <a class="header-anchor" href="#technical-interview-questions-answers-150-questions" aria-label="Permalink to &quot;Technical Interview Questions &amp; Answers (150+ Questions)&quot;">​</a></h1><p>This comprehensive interview guide prepares engineers to defend every design decision, algorithmic choice, and financial invariant implemented in <code>19-usage-billing-engine</code>.</p><hr><h2 id="_1-project-overview-executive-pitch" tabindex="-1">1. Project Overview &amp; Executive Pitch <a class="header-anchor" href="#_1-project-overview-executive-pitch" aria-label="Permalink to &quot;1. Project Overview &amp; Executive Pitch&quot;">​</a></h2><h3 id="q1-walk-me-through-your-project-in-3-minutes" tabindex="-1">Q1: Walk me through your project in 3 minutes. <a class="header-anchor" href="#q1-walk-me-through-your-project-in-3-minutes" aria-label="Permalink to &quot;Q1: Walk me through your project in 3 minutes.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;I built <strong>19-Usage-Billing-Engine</strong>, an asynchronous metered billing and financial rating engine written in Python 3.13, FastAPI, PostgreSQL 16, and Vanilla JavaScript. The platform solves the central challenge of usage-based pricing: converting high-frequency consumption events—like API calls, database storage, and compute seconds—into mathematically exact, audit-compliant customer invoices. At the ingestion layer, client microservices emit usage events with cryptographic idempotency keys. In <code>metering/ingestion.py</code>, our pipeline validates the payload schema, verifies that timestamps fall within a valid 90-day window, and checks a composite database index. If network timeouts cause a client to retry, the duplicate is recognized in constant time and acknowledged without double-billing. At the rating layer, in <code>rating/engine.py</code>, our engine evaluates raw usage against versioned price books. It supports diverse billing models: flat subscriptions, per-unit metering, volume discounts, and graduated slab tiers. All calculations are executed in integer minor units (cents) or fixed-point Decimal arithmetic with <code>ROUND_HALF_UP</code>, completely eliminating floating-point rounding drift. At the accounting layer, in <code>models/ledger.py</code>, the system maintains an immutable double-entry ledger. Every invoice finalization or payment capture writes a balanced transaction requiring that the sum of debits strictly equals the sum of credits across at least two entries. At period close, in <code>invoicing/manager.py</code>, the engine locks customer meters, aggregates line items, applies taxes and discounts, and uses row-level locking on sequence counters to assign a gapless legal invoice number like <code>INV-2026-0042</code>. The customer console provides real-time visibility into MRR, ARR, and line-item breakdowns. The entire codebase is verified by 87 automated tests running via Pytest.&quot;</p><h3 id="q2-give-me-your-60-second-elevator-pitch" tabindex="-1">Q2: Give me your 60-second elevator pitch. <a class="header-anchor" href="#q2-give-me-your-60-second-elevator-pitch" aria-label="Permalink to &quot;Q2: Give me your 60-second elevator pitch.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;I designed and built an enterprise metered billing and rating engine that processes millions of raw consumption events into exact customer invoices. It features an idempotent ingestion pipeline that guarantees exactly-once accounting under network retries, a mathematical rating engine supporting complex tiered and graduated pricing models, and an append-only double-entry ledger that strictly enforces debit-credit conservation. It handles gapless invoice numbering, second-exact mid-cycle subscription proration, and automated dunning workflows.&quot;</p><h3 id="q3-what-core-business-problem-does-this-engine-solve" tabindex="-1">Q3: What core business problem does this engine solve? <a class="header-anchor" href="#q3-what-core-business-problem-does-this-engine-solve" aria-label="Permalink to &quot;Q3: What core business problem does this engine solve?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;As companies shift from flat SaaS subscriptions to usage-based pricing, billing errors become their largest revenue risk. Out-of-order event delivery causes missing charges, network retries cause double-billing, floating-point rounding errors lead to discrepancies on tax filings, and mid-cycle plan upgrades result in customer disputes. This engine eliminates these risks through database-level idempotency, exact integer arithmetic, and double-entry accounting guarantees.&quot;</p><h3 id="q4-who-are-the-primary-users-of-this-system" tabindex="-1">Q4: Who are the primary users of this system? <a class="header-anchor" href="#q4-who-are-the-primary-users-of-this-system" aria-label="Permalink to &quot;Q4: Who are the primary users of this system?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;There are three primary personas:</p><ol><li><strong>Developer Services</strong>: Microservices reporting consumption via high-throughput HTTP endpoints.</li><li><strong>Finance &amp; Accounting Teams</strong>: Internal staff managing pricing tiers, auditing ledger journals, and finalizing invoices.</li><li><strong>Tenant Customers</strong>: B2B clients viewing real-time accrued charges and downloading finalized invoices.&quot;</li></ol><h3 id="q5-what-makes-metered-billing-fundamentally-harder-than-traditional-subscription-billing" tabindex="-1">Q5: What makes metered billing fundamentally harder than traditional subscription billing? <a class="header-anchor" href="#q5-what-makes-metered-billing-fundamentally-harder-than-traditional-subscription-billing" aria-label="Permalink to &quot;Q5: What makes metered billing fundamentally harder than traditional subscription billing?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In subscription billing, charges are static and known in advance (e.g., $50 on the 1st of every month). In metered billing:</p><ol><li>Volume is unpredictable and arrives in millions of discrete events.</li><li>Events arrive out of order and across network boundaries.</li><li>Rating logic is non-linear (graduated tiers where price changes dynamically as volume increases).</li><li>Billing periods must lock usage before rating to prevent race conditions from concurrent incoming events.&quot;</li></ol><h3 id="q6-what-is-the-hardest-function-in-the-codebase-explain-it-line-by-line" tabindex="-1">Q6: What is the hardest function in the codebase? Explain it line by line. <a class="header-anchor" href="#q6-what-is-the-hardest-function-in-the-codebase-explain-it-line-by-line" aria-label="Permalink to &quot;Q6: What is the hardest function in the codebase? Explain it line by line.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The hardest function is <code>calculate_proration()</code> in <code>models/proration.py:L31-L77</code>.</p><ul><li><strong>Lines 42-49</strong>: Normalizes all datetimes (<code>period_start</code>, <code>period_end</code>, <code>effective_time</code>) to UTC and clamps the effective time within the period boundaries to prevent negative time intervals.</li><li><strong>Lines 51-56</strong>: Calculates <code>total_seconds</code> and <code>remaining_seconds</code> as <code>Decimal</code> objects: <code>remaining_seconds = Decimal(str((period_end - effective_time).total_seconds()))</code>. Using <code>str()</code> conversion is critical because converting a float directly into <code>Decimal</code> retains IEEE 754 precision artifacts.</li><li><strong>Line 56</strong>: Computes the exact time fraction: <code>fraction = remaining_seconds / total_seconds</code>.</li><li><strong>Line 59</strong>: Computes unused credit from the old plan: <code>(Decimal(old_plan_price_cents) * fraction).quantize(Decimal(&#39;1&#39;), rounding=ROUND_HALF_UP)</code>. This calculates the exact cents owed back to the customer, rounded using bankers&#39; rounding standards.</li><li><strong>Line 61</strong>: Computes new plan charge for the remaining period: <code>(Decimal(new_plan_price_cents) * fraction).quantize(Decimal(&#39;1&#39;), rounding=ROUND_HALF_UP)</code>.</li><li><strong>Lines 63-65</strong>: Subtracts <code>unused_credit</code> from <code>new_charge</code> to yield <code>net_proration_cents</code>. This produces exact integer cents with zero rounding drift.&quot;</li></ul><h3 id="q7-what-bugs-did-you-encounter-during-development-and-how-did-you-resolve-them" tabindex="-1">Q7: What bugs did you encounter during development and how did you resolve them? <a class="header-anchor" href="#q7-what-bugs-did-you-encounter-during-development-and-how-did-you-resolve-them" aria-label="Permalink to &quot;Q7: What bugs did you encounter during development and how did you resolve them?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The most difficult bug was a race condition in gapless invoice numbering. Under concurrent finalization requests, multiple workers read the same sequence number from the database and attempted to insert duplicate invoice numbers, causing unique constraint violations. I solved this in <code>invoicing/manager.py:L245</code> by introducing a dedicated <code>invoice_sequences</code> table and acquiring an exclusive row lock using SQLAlchemy&#39;s <code>.with_for_update()</code>. This serialized the finalization queue without locking the entire invoices table.&quot;</p><h3 id="q8-what-would-you-change-if-you-rebuilt-this-system-from-scratch" tabindex="-1">Q8: What would you change if you rebuilt this system from scratch? <a class="header-anchor" href="#q8-what-would-you-change-if-you-rebuilt-this-system-from-scratch" aria-label="Permalink to &quot;Q8: What would you change if you rebuilt this system from scratch?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;I would place an Apache Kafka or AWS Kinesis stream in front of the ingestion pipeline. Currently, events hit FastAPI and perform synchronous PostgreSQL inserts. While adequate up to 5,000 events/second, scaling to 100,000 events/second requires streaming ingestion where events are batched into micro-shards before hitting relational storage.&quot;</p><h3 id="q9-why-did-you-choose-python-and-fastapi-instead-of-go-or-node-js" tabindex="-1">Q9: Why did you choose Python and FastAPI instead of Go or Node.js? <a class="header-anchor" href="#q9-why-did-you-choose-python-and-fastapi-instead-of-go-or-node-js" aria-label="Permalink to &quot;Q9: Why did you choose Python and FastAPI instead of Go or Node.js?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;FastAPI gave us asynchronous performance comparable to Node.js via uvloop, but with two decisive advantages for fintech:</p><ol><li>Pydantic v2&#39;s compile-time data validation for incoming telemetry.</li><li>Python&#39;s native <code>Decimal</code> module and data-science ecosystem for pricing modeling and spend forecasting.&quot;</li></ol><h3 id="q10-how-do-you-prevent-floating-point-rounding-errors-in-calculations" tabindex="-1">Q10: How do you prevent floating-point rounding errors in calculations? <a class="header-anchor" href="#q10-how-do-you-prevent-floating-point-rounding-errors-in-calculations" aria-label="Permalink to &quot;Q10: How do you prevent floating-point rounding errors in calculations?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;We enforce a zero-float policy across all financial paths. All balances, unit prices, line items, and totals are represented as integer minor units (cents) stored in SQL <code>BIGINT</code> columns. Where fractional rates occur (e.g. $0.0015 per API call), we use Python&#39;s <code>Decimal</code> type with explicit <code>.quantize(Decimal(&#39;1&#39;), rounding=ROUND_HALF_UP)</code>.&quot;</p><h3 id="q11-how-is-multi-tenancy-handled-in-this-architecture" tabindex="-1">Q11: How is multi-tenancy handled in this architecture? <a class="header-anchor" href="#q11-how-is-multi-tenancy-handled-in-this-architecture" aria-label="Permalink to &quot;Q11: How is multi-tenancy handled in this architecture?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;We implement row-level multi-tenancy. Every core database table (<code>usage_events</code>, <code>invoices</code>, <code>ledger_transactions</code>, <code>api_keys</code>) includes an indexed <code>tenant_id</code> column. All database queries must include <code>WHERE tenant_id = :tenant_id</code>, and our authentication layer enforces deny-by-default cross-tenant isolation.&quot;</p><h3 id="q12-how-does-the-system-handle-late-or-out-of-order-events" tabindex="-1">Q12: How does the system handle late or out-of-order events? <a class="header-anchor" href="#q12-how-does-the-system-handle-late-or-out-of-order-events" aria-label="Permalink to &quot;Q12: How does the system handle late or out-of-order events?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Events carry an event timestamp representing when consumption occurred, distinct from ingestion timestamp. If an event arrives for an open billing period, it is aggregated normally. If it arrives after that period has closed, our period engine routes the event into the customer&#39;s <em>current</em> open period as a prior-period adjustment line item.&quot;</p><h3 id="q13-what-is-the-difference-between-volume-pricing-and-graduated-pricing" tabindex="-1">Q13: What is the difference between volume pricing and graduated pricing? <a class="header-anchor" href="#q13-what-is-the-difference-between-volume-pricing-and-graduated-pricing" aria-label="Permalink to &quot;Q13: What is the difference between volume pricing and graduated pricing?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <strong>Volume Pricing</strong>, the achieved tier determines the price for <em>all</em> units. For example, if Tier 1 (1-100) is $0.10 and Tier 2 (101+) is $0.05, consuming 150 units costs $150 \\times $0.05 = $7.50$. In <strong>Graduated (Bracket) Pricing</strong>, usage is sliced across progressive tiers. The first 100 units cost $0.10 ($10), and the remaining 50 units cost $0.05 ($2.50), totaling $12.50.&quot;</p><h3 id="q14-how-do-you-ensure-legal-compliance-with-gapless-invoice-numbering" tabindex="-1">Q14: How do you ensure legal compliance with gapless invoice numbering? <a class="header-anchor" href="#q14-how-do-you-ensure-legal-compliance-with-gapless-invoice-numbering" aria-label="Permalink to &quot;Q14: How do you ensure legal compliance with gapless invoice numbering?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Fiscal regulations in Germany, France, and other jurisdictions require that invoice numbers have no gaps (e.g., <code>INV-2026-0001</code>, <code>0002</code>). We maintain an <code>invoice_sequences</code> row per tenant and year. During finalization, the worker acquires an exclusive row lock (<code>SELECT ... FOR UPDATE</code>), increments the counter, and assigns the number within the same transaction that finalizes the invoice.&quot;</p><h3 id="q15-how-does-the-double-entry-ledger-maintain-integrity-if-a-worker-crashes" tabindex="-1">Q15: How does the double-entry ledger maintain integrity if a worker crashes? <a class="header-anchor" href="#q15-how-does-the-double-entry-ledger-maintain-integrity-if-a-worker-crashes" aria-label="Permalink to &quot;Q15: How does the double-entry ledger maintain integrity if a worker crashes?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Every ledger transaction and its constituent entries (at least 2 entries) are inserted inside a single ACID database transaction. If the worker crashes or debits do not equal credits, the database rolls back the transaction, leaving no partial or orphaned ledger entries.&quot;</p><hr><h2 id="_2-system-architecture-high-scale-design" tabindex="-1">2. System Architecture &amp; High-Scale Design <a class="header-anchor" href="#_2-system-architecture-high-scale-design" aria-label="Permalink to &quot;2. System Architecture &amp; High-Scale Design&quot;">​</a></h2><h3 id="q16-describe-the-high-level-architecture-of-the-platform" tabindex="-1">Q16: Describe the high-level architecture of the platform. <a class="header-anchor" href="#q16-describe-the-high-level-architecture-of-the-platform" aria-label="Permalink to &quot;Q16: Describe the high-level architecture of the platform.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;It is a layered asynchronous architecture:</p><ol><li><strong>API Gateway Layer</strong>: FastAPI application managing auth, rate limiting, and REST routing.</li><li><strong>Ingestion &amp; Validation Engine</strong>: Asynchronous pipeline validating schemas and checking idempotency.</li><li><strong>Rating &amp; Pricing Engine</strong>: Pure in-memory rating logic calculating tiered and graduated totals.</li><li><strong>Billing &amp; Invoicing Manager</strong>: Manages period lifecycles, locks meters, and aggregates invoices.</li><li><strong>Double-Entry Ledger</strong>: Append-only transaction journal enforcing balance conservation.</li><li><strong>Storage Layer</strong>: PostgreSQL 16 time-partitioned tables and Redis for real-time counters.&quot;</li></ol><h3 id="q17-why-is-the-express-fastapi-app-separated-from-the-server-runner" tabindex="-1">Q17: Why is the express/FastAPI app separated from the server runner? <a class="header-anchor" href="#q17-why-is-the-express-fastapi-app-separated-from-the-server-runner" aria-label="Permalink to &quot;Q17: Why is the express/FastAPI app separated from the server runner?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>api/app.py</code>, the <code>FastAPI()</code> application instance, routers, and middleware are defined without calling <code>uvicorn.run()</code>. This separation allows test suites (like <code>pytest</code>) to mount the app directly via <code>httpx.AsyncClient</code> without binding to physical network ports, and enables production deployments to run multi-worker process managers like Gunicorn.&quot;</p><h3 id="q18-how-do-you-partition-the-usage-events-table-in-postgresql" tabindex="-1">Q18: How do you partition the usage events table in PostgreSQL? <a class="header-anchor" href="#q18-how-do-you-partition-the-usage-events-table-in-postgresql" aria-label="Permalink to &quot;Q18: How do you partition the usage events table in PostgreSQL?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;We use PostgreSQL declarative range partitioning by month on the <code>timestamp</code> column: <code>CREATE TABLE usage_events (...) PARTITION BY RANGE (timestamp);</code> Partitions are created for each calendar month (e.g., <code>usage_events_2026_10</code>). When querying by date range, PostgreSQL performs partition pruning, scanning only relevant month tables rather than a multi-billion row table.&quot;</p><h3 id="q19-what-happens-when-usage-event-volume-grows-from-500-sec-to-50-000-sec" tabindex="-1">Q19: What happens when usage event volume grows from 500/sec to 50,000/sec? <a class="header-anchor" href="#q19-what-happens-when-usage-event-volume-grows-from-500-sec-to-50-000-sec" aria-label="Permalink to &quot;Q19: What happens when usage event volume grows from 500/sec to 50,000/sec?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;At 50,000/sec:</p><ol><li>Synchronous database writes would saturate disk IOPS.</li><li>We decouple ingestion by placing Apache Kafka in front of workers.</li><li>Workers batch 1,000 events into single SQL <code>INSERT ... VALUES</code> statements.</li><li>Redis Bloom filters are used for sub-millisecond idempotency deduplication before touching PostgreSQL.&quot;</li></ol><h3 id="q20-explain-the-cap-theorem-trade-offs-in-this-billing-engine" tabindex="-1">Q20: Explain the CAP theorem trade-offs in this billing engine. <a class="header-anchor" href="#q20-explain-the-cap-theorem-trade-offs-in-this-billing-engine" aria-label="Permalink to &quot;Q20: Explain the CAP theorem trade-offs in this billing engine.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Billing engines are firmly CP systems (Consistency and Partition Tolerance). In financial accounting, an inconsistent state (like double-charging a customer or losing track of ledger balances) is legally and commercially unacceptable. If a network partition occurs between database replicas, we reject writes rather than accept unverified usage.&quot;</p><h3 id="q21-what-is-differential-testing-and-how-do-you-use-it-for-aggregation" tabindex="-1">Q21: What is differential testing and how do you use it for aggregation? <a class="header-anchor" href="#q21-what-is-differential-testing-and-how-do-you-use-it-for-aggregation" aria-label="Permalink to &quot;Q21: What is differential testing and how do you use it for aggregation?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Differential testing verifies an optimized system against an unoptimized reference implementation. In <code>aggregation/periods.py</code>, we pre-aggregate usage into hourly rollups for fast UI queries. During period close, our test executes <code>recompute_from_scratch()</code>, which executes a direct SQL <code>SUM()</code> over raw usage events, proving mathematically that cached rollups equal raw telemetry.&quot;</p><h3 id="q22-what-caching-strategy-is-applied-to-usage-counters" tabindex="-1">Q22: What caching strategy is applied to usage counters? <a class="header-anchor" href="#q22-what-caching-strategy-is-applied-to-usage-counters" aria-label="Permalink to &quot;Q22: What caching strategy is applied to usage counters?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;We use a Write-Through caching strategy with Redis. When events are ingested, raw events are written to PostgreSQL while Redis atomic counters (<code>INCRBY</code>) are updated for real-time dashboard meters. The database remains the authoritative persistent source of truth.&quot;</p><h3 id="q23-how-do-you-prevent-cache-stampede-during-end-of-month-billing" tabindex="-1">Q23: How do you prevent cache stampede during end-of-month billing? <a class="header-anchor" href="#q23-how-do-you-prevent-cache-stampede-during-end-of-month-billing" aria-label="Permalink to &quot;Q23: How do you prevent cache stampede during end-of-month billing?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When hundreds of billing periods close simultaneously, workers do not query dynamic cache keys. Instead, closing periods read from immutable database snapshots using cursor-based pagination, completely avoiding cache stampede or thundering herd problems.&quot;</p><h3 id="q24-what-is-the-purpose-of-the-manual-clock-simulator-in-clock-py" tabindex="-1">Q24: What is the purpose of the manual clock simulator in <code>clock.py</code>? <a class="header-anchor" href="#q24-what-is-the-purpose-of-the-manual-clock-simulator-in-clock-py" aria-label="Permalink to &quot;Q24: What is the purpose of the manual clock simulator in `clock.py`?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Billing schedules (like 30-day invoice due dates and 14-day dunning grace periods) cannot be tested reliably using <code>time.sleep()</code>. The <code>ManualClock</code> provides an injectable time provider that allows automated test suites to fast-forward days or weeks in milliseconds to verify dunning state transitions deterministically.&quot;</p><h3 id="q25-why-is-the-usage-ledger-append-only" tabindex="-1">Q25: Why is the usage ledger append-only? <a class="header-anchor" href="#q25-why-is-the-usage-ledger-append-only" aria-label="Permalink to &quot;Q25: Why is the usage ledger append-only?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In financial accounting, you never delete or update historical entries. If an invoice was billed incorrectly, modifying the original record destroys the audit trail. Instead, an append-only ledger records a new <em>reversing entry</em> or adjustment transaction, ensuring full traceability for SOC 1 and SOX compliance.&quot;</p><hr><h2 id="_3-core-feature-implementations-code-deep-dives" tabindex="-1">3. Core Feature Implementations &amp; Code Deep Dives <a class="header-anchor" href="#_3-core-feature-implementations-code-deep-dives" aria-label="Permalink to &quot;3. Core Feature Implementations &amp; Code Deep Dives&quot;">​</a></h2><h3 id="q26-explain-the-graduated-tier-rating-algorithm-in-rating-engine-py" tabindex="-1">Q26: Explain the graduated tier rating algorithm in <code>rating/engine.py</code>. <a class="header-anchor" href="#q26-explain-the-graduated-tier-rating-algorithm-in-rating-engine-py" aria-label="Permalink to &quot;Q26: Explain the graduated tier rating algorithm in `rating/engine.py`.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The algorithm sorts tiers by upper bound (<code>up_to</code>). It maintains a <code>remaining</code> counter equal to billable units. For each tier, it computes the bracket size (<code>up_to - prev_bound</code>). It charges <code>min(remaining, bracket_size)</code> at that tier&#39;s unit price, decrements <code>remaining</code>, and advances <code>prev_bound</code>. Any remaining units past the highest bound are charged at the unbounded top tier rate.&quot;</p><h3 id="q27-how-does-convert-usage-unit-handle-incompatible-unit-conversions" tabindex="-1">Q27: How does <code>convert_usage_unit</code> handle incompatible unit conversions? <a class="header-anchor" href="#q27-how-does-convert-usage-unit-handle-incompatible-unit-conversions" aria-label="Permalink to &quot;Q27: How does `convert_usage_unit` handle incompatible unit conversions?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>metering/ingestion.py:L42-L69</code>, the converter maintains discrete multiplier tables for storage (Bytes to GB) and time (Milliseconds to Hours). If a caller attempts to convert an incompatible dimension—such as Megabytes to Seconds—the function detects that the units belong to different multiplier tables and raises a <code>ValueError(&#39;Incompatible unit conversion&#39;)</code>.&quot;</p><h3 id="q28-how-does-the-system-enforce-minimum-charge-floors-and-maximum-caps" tabindex="-1">Q28: How does the system enforce minimum charge floors and maximum caps? <a class="header-anchor" href="#q28-how-does-the-system-enforce-minimum-charge-floors-and-maximum-caps" aria-label="Permalink to &quot;Q28: How does the system enforce minimum charge floors and maximum caps?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>rating/engine.py:L166-L178</code>, after calculating line item subtotal and flat fees:</p><ol><li>If <code>min_charge_cents &gt; 0</code> and <code>total_cents &lt; min_charge_cents</code>, total is clamped to <code>min_charge_cents</code> and <code>min_charge_applied</code> flag is set to true.</li><li>If <code>max_charge_cents</code> is defined and <code>total_cents &gt; max_charge_cents</code>, total is clamped to <code>max_charge_cents</code> and <code>max_charge_applied</code> flag is set to true.&quot;</li></ol><h3 id="q29-what-happens-when-an-idempotency-key-is-submitted-with-a-different-payload" tabindex="-1">Q29: What happens when an idempotency key is submitted with a different payload? <a class="header-anchor" href="#q29-what-happens-when-an-idempotency-key-is-submitted-with-a-different-payload" aria-label="Permalink to &quot;Q29: What happens when an idempotency key is submitted with a different payload?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Our unique index <code>ix_tenant_idem</code> enforces uniqueness on <code>(tenant_id, idempotency_key)</code>. If a duplicate key arrives, the system queries the existing event and verifies attributes. If parameters differ, it returns the original cached record or raises an idempotency conflict error, preventing payload substitution attacks.&quot;</p><h3 id="q30-how-does-subscriptionlifecyclemanager-handle-plan-version-immutability" tabindex="-1">Q30: How does <code>SubscriptionLifecycleManager</code> handle plan version immutability? <a class="header-anchor" href="#q30-how-does-subscriptionlifecyclemanager-handle-plan-version-immutability" aria-label="Permalink to &quot;Q30: How does `SubscriptionLifecycleManager` handle plan version immutability?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>models/plan_versions.py</code>, when an invoice is finalized against a plan version, the plan record&#39;s <code>is_locked</code> boolean is set to true. Any subsequent attempt to modify rates or tiers on that plan ID automatically increments the version counter (<code>v1 -&gt; v2</code>), ensuring historical invoices remain tied to immutable snapshots.&quot;</p><h3 id="q31-how-does-the-dunning-engine-transition-accounts-from-past-due-to-suspended" tabindex="-1">Q31: How does the dunning engine transition accounts from <code>PAST_DUE</code> to <code>SUSPENDED</code>? <a class="header-anchor" href="#q31-how-does-the-dunning-engine-transition-accounts-from-past-due-to-suspended" aria-label="Permalink to &quot;Q31: How does the dunning engine transition accounts from `PAST_DUE` to `SUSPENDED`?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>payments/collections.py:L65-L334</code>, each dunning record stores a <code>grace_period_until</code> timestamp (e.g. 14 days after invoice due date). When <code>execute_dunning_step()</code> is invoked, if the current timestamp exceeds <code>grace_period_until</code> and payment remains uncollected, <code>account.standing</code> is updated to <code>SUSPENDED</code> and an audit entry is generated.&quot;</p><h3 id="q32-explain-the-two-step-payment-authorization-and-capture-flow" tabindex="-1">Q32: Explain the two-step payment authorization and capture flow. <a class="header-anchor" href="#q32-explain-the-two-step-payment-authorization-and-capture-flow" aria-label="Permalink to &quot;Q32: Explain the two-step payment authorization and capture flow.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;1. <code>authorize_payment()</code> contacts the gateway to place a hold on customer funds without settling, creating a <code>PaymentRecord</code> in status <code>AUTHORIZED</code>. 2. <code>capture_payment()</code> settles the authorized funds, marks the payment <code>CAPTURED</code>, sets the invoice to <code>PAID</code>, and posts a ledger transaction debiting Cash and crediting Accounts Receivable.&quot;</p><h3 id="q33-how-does-the-api-validate-incoming-timestamp-clock-drift" tabindex="-1">Q33: How does the API validate incoming timestamp clock drift? <a class="header-anchor" href="#q33-how-does-the-api-validate-incoming-timestamp-clock-drift" aria-label="Permalink to &quot;Q33: How does the API validate incoming timestamp clock drift?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>metering/ingestion.py:L142-L146</code>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> event_ts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timedelta(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">days</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;TIMESTAMP_TOO_OLD&#39;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> event_ts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timedelta(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">hours</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;TIMESTAMP_IN_FUTURE&#39;</span></span></code></pre></div><p>This protects the billing engine from accepting stale events that would invalidate closed accounting periods, while tolerating up to 1 hour of client clock drift.&quot;</p><h3 id="q34-what-data-structure-is-used-to-serialize-dimensions-in-usage-events" tabindex="-1">Q34: What data structure is used to serialize dimensions in <code>usage_events</code>? <a class="header-anchor" href="#q34-what-data-structure-is-used-to-serialize-dimensions-in-usage-events" aria-label="Permalink to &quot;Q34: What data structure is used to serialize dimensions in `usage_events`?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Dimensions are serialized as a deterministic, sorted JSON string (<code>json.dumps(dims, sort_keys=True)</code>). This ensures consistent byte representation and allows indexing or hashing across dimensions.&quot;</p><h3 id="q35-how-does-the-system-compute-monthly-recurring-revenue-mrr" tabindex="-1">Q35: How does the system compute Monthly Recurring Revenue (MRR)? <a class="header-anchor" href="#q35-how-does-the-system-compute-monthly-recurring-revenue-mrr" aria-label="Permalink to &quot;Q35: How does the system compute Monthly Recurring Revenue (MRR)?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>reporting/metrics.py:L91-L128</code>, <code>compute_mrr_metrics()</code> sums the monthly subscription rates of all active subscriptions (<code>status == &#39;ACTIVE&#39;</code>). For annual plans, it divides the annual fee by 12. Annual Recurring Revenue (ARR) is calculated as $\\text{MRR} \\times 12$.&quot;</p><hr><h2 id="_4-database-indexes-financial-integrity" tabindex="-1">4. Database, Indexes &amp; Financial Integrity <a class="header-anchor" href="#_4-database-indexes-financial-integrity" aria-label="Permalink to &quot;4. Database, Indexes &amp; Financial Integrity&quot;">​</a></h2><h3 id="q36-why-use-composite-indexes-like-ix-usage-tenant-cust-type-time" tabindex="-1">Q36: Why use composite indexes like <code>ix_usage_tenant_cust_type_time</code>? <a class="header-anchor" href="#q36-why-use-composite-indexes-like-ix-usage-tenant-cust-type-time" aria-label="Permalink to &quot;Q36: Why use composite indexes like `ix_usage_tenant_cust_type_time`?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Queries filtering by tenant, customer, event type, and date range are the most frequent operations during billing period rollups. A 4-column composite index allows PostgreSQL to perform an index-only scan, retrieving matching rows in $O(\\log N)$ time without touching table heap pages.&quot;</p><h3 id="q37-what-is-the-exact-mathematical-invariant-of-the-double-entry-ledger" tabindex="-1">Q37: What is the exact mathematical invariant of the double-entry ledger? <a class="header-anchor" href="#q37-what-is-the-exact-mathematical-invariant-of-the-double-entry-ledger" aria-label="Permalink to &quot;Q37: What is the exact mathematical invariant of the double-entry ledger?&quot;">​</a></h3>',92),e("p",null,[e("strong",null,"Answer"),n(': "For every transaction $T$: $$\\sum_{i=1}^{n} \\text{Debits}'),e("em",{j:"1"},"i == \\sum"),n('^{m} \\text{Credits}_j \\quad \\text{where } n + m \\ge 2 \\text{ and } \\text{Amount} > 0$$ Globally, across all accounts in a tenant ledger: $$\\sum \\text{All Debits} == \\sum \\text{All Credits}$$"')],-1),a('<h3 id="q38-how-does-postgresql-handle-row-level-locking-during-invoice-finalization" tabindex="-1">Q38: How does PostgreSQL handle row-level locking during invoice finalization? <a class="header-anchor" href="#q38-how-does-postgresql-handle-row-level-locking-during-invoice-finalization" aria-label="Permalink to &quot;Q38: How does PostgreSQL handle row-level locking during invoice finalization?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When executing <code>SELECT ... FROM invoice_sequences WHERE tenant_id = :t FOR UPDATE</code>, PostgreSQL places an exclusive row-level lock (<code>X</code> lock) on that sequence record. Concurrent transactions attempting to finalize invoices for the same tenant are placed in a queue until the first transaction commits, guaranteeing gapless sequential numbers.&quot;</p><h3 id="q39-what-is-the-trade-off-between-soft-deletes-and-hard-deletes-in-billing" tabindex="-1">Q39: What is the trade-off between soft deletes and hard deletes in billing? <a class="header-anchor" href="#q39-what-is-the-trade-off-between-soft-deletes-and-hard-deletes-in-billing" aria-label="Permalink to &quot;Q39: What is the trade-off between soft deletes and hard deletes in billing?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Financial platforms strictly prohibit hard deletes. Deleting a record destroys audit trails and invalidates historical reconciliations. We use status flags (<code>VOID</code>, <code>INACTIVE</code>, <code>REVOKED</code>), ensuring every historical invoice and transaction remains permanently inspectable.&quot;</p><h3 id="q40-how-do-you-verify-that-postgresql-query-partition-pruning-is-working" tabindex="-1">Q40: How do you verify that PostgreSQL query partition pruning is working? <a class="header-anchor" href="#q40-how-do-you-verify-that-postgresql-query-partition-pruning-is-working" aria-label="Permalink to &quot;Q40: How do you verify that PostgreSQL query partition pruning is working?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;By executing <code>EXPLAIN</code> on a query filtering by timestamp. When partition pruning is active, the query plan shows <code>Append</code> or <code>Seq Scan on usage_events_2026_10</code> and explicitly marks non-matching partitions as <code>(never executed)</code>.&quot;</p><hr><h2 id="_5-security-auth-owasp-defenses" tabindex="-1">5. Security, Auth &amp; OWASP Defenses <a class="header-anchor" href="#_5-security-auth-owasp-defenses" aria-label="Permalink to &quot;5. Security, Auth &amp; OWASP Defenses&quot;">​</a></h2><h3 id="q41-how-are-api-keys-stored-and-verified" tabindex="-1">Q41: How are API keys stored and verified? <a class="header-anchor" href="#q41-how-are-api-keys-stored-and-verified" aria-label="Permalink to &quot;Q41: How are API keys stored and verified?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When an API key is generated via <code>AuthManager.create_api_key()</code>, a 32-byte cryptographically secure token (<code>bil_role_...</code>) is generated. The raw token is returned once to the caller. The database stores only the SHA-256 hash (<code>key_hash</code>). Verification hashes the incoming bearer token and performs an indexed lookup against <code>api_keys</code>.&quot;</p><h3 id="q42-explain-the-deny-by-default-rbac-implementation" tabindex="-1">Q42: Explain the deny-by-default RBAC implementation. <a class="header-anchor" href="#q42-explain-the-deny-by-default-rbac-implementation" aria-label="Permalink to &quot;Q42: Explain the deny-by-default RBAC implementation.&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>security/auth.py</code>, each role (<code>OWNER</code>, <code>FINANCE</code>, <code>VIEWER</code>, <code>SERVICE</code>) is mapped to an explicit set of permission strings. When an endpoint is accessed, the authorization dependency verifies that the caller&#39;s role possesses the required permission. If the role or permission is unmapped, access is denied (403 Forbidden).&quot;</p><h3 id="q43-how-does-the-system-prevent-pii-and-credit-card-numbers-from-entering-audit-logs" tabindex="-1">Q43: How does the system prevent PII and credit card numbers from entering audit logs? <a class="header-anchor" href="#q43-how-does-the-system-prevent-pii-and-credit-card-numbers-from-entering-audit-logs" aria-label="Permalink to &quot;Q43: How does the system prevent PII and credit card numbers from entering audit logs?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>security/audit.py</code>, <code>redact_sensitive_info()</code> recursively inspects before/after state dictionaries. It matches dictionary keys against sensitive terms (<code>tax_id</code>, <code>ssn</code>, <code>card_number</code>, <code>cvv</code>) and runs regular expressions against string values, replacing credit cards and tax IDs with <code>[REDACTED]</code> before writing to the database.&quot;</p><h3 id="q44-how-does-the-application-defend-against-sql-injection" tabindex="-1">Q44: How does the application defend against SQL injection? <a class="header-anchor" href="#q44-how-does-the-application-defend-against-sql-injection" aria-label="Permalink to &quot;Q44: How does the application defend against SQL injection?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;We use SQLAlchemy 2.0 async queries with explicit parameter binding (<code>select().where(...)</code>). No SQL statements are constructed using string concatenation or f-strings.&quot;</p><h3 id="q45-how-do-you-protect-against-cross-origin-resource-sharing-cors-attacks" tabindex="-1">Q45: How do you protect against Cross-Origin Resource Sharing (CORS) attacks? <a class="header-anchor" href="#q45-how-do-you-protect-against-cross-origin-resource-sharing-cors-attacks" aria-label="Permalink to &quot;Q45: How do you protect against Cross-Origin Resource Sharing (CORS) attacks?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Starlette&#39;s <code>CORSMiddleware</code> explicitly defines allowed origins, methods, and headers. In production, <code>allow_origins</code> is restricted to authorized billing console domains rather than wildcard <code>*</code>.&quot;</p><hr><h2 id="_6-performance-scaling-concurrency" tabindex="-1">6. Performance, Scaling &amp; Concurrency <a class="header-anchor" href="#_6-performance-scaling-concurrency" aria-label="Permalink to &quot;6. Performance, Scaling &amp; Concurrency&quot;">​</a></h2><h3 id="q46-what-is-little-s-law-and-how-does-it-apply-to-our-ingestion-pipeline" tabindex="-1">Q46: What is Little&#39;s Law and how does it apply to our ingestion pipeline? <a class="header-anchor" href="#q46-what-is-little-s-law-and-how-does-it-apply-to-our-ingestion-pipeline" aria-label="Permalink to &quot;Q46: What is Little&#39;s Law and how does it apply to our ingestion pipeline?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Little&#39;s Law states: $L = \\lambda \\times W$, where $L$ is concurrency, $\\lambda$ is throughput, and $W$ is latency. If our ingestion pipeline handles $\\lambda = 10,000$ events/second with an average latency of $W = 10\\text{ms}$ ($0.01\\text{s}$), the system must maintain $L = 100$ concurrent database connections in the connection pool to prevent request queueing.&quot;</p><h3 id="q47-how-does-connection-pooling-prevent-database-starvation" tabindex="-1">Q47: How does connection pooling prevent database starvation? <a class="header-anchor" href="#q47-how-does-connection-pooling-prevent-database-starvation" aria-label="Permalink to &quot;Q47: How does connection pooling prevent database starvation?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Without pooling, each incoming request opens a new TCP connection, exhausting PostgreSQL&#39;s <code>max_connections</code> (causing fatal connection errors). Our pool maintains 20 warm connections with up to 10 overflow connections, queueing excess requests gracefully.&quot;</p><h3 id="q48-what-is-the-time-complexity-of-the-graduated-rating-calculation" tabindex="-1">Q48: What is the time complexity of the graduated rating calculation? <a class="header-anchor" href="#q48-what-is-the-time-complexity-of-the-graduated-rating-calculation" aria-label="Permalink to &quot;Q48: What is the time complexity of the graduated rating calculation?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Time complexity is $O(T)$, where $T$ is the number of configured pricing tiers. Because tiers rarely exceed 5 to 10 brackets, the algorithm executes in constant time ($O(1)$) with sub-microsecond latency.&quot;</p><h3 id="q49-how-do-you-handle-database-deadlocks-during-concurrent-billing-cycles" tabindex="-1">Q49: How do you handle database deadlocks during concurrent billing cycles? <a class="header-anchor" href="#q49-how-do-you-handle-database-deadlocks-during-concurrent-billing-cycles" aria-label="Permalink to &quot;Q49: How do you handle database deadlocks during concurrent billing cycles?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Deadlocks occur when concurrent transactions acquire locks in different orders (e.g., Transaction A locks Invoice 1 then Invoice 2, while Transaction B locks Invoice 2 then Invoice 1). We eliminate deadlocks by enforcing deterministic lock acquisition ordering—sorting resource IDs alphabetically before requesting locks.&quot;</p><h3 id="q50-how-does-the-frontend-maintain-high-performance-without-a-virtual-dom" tabindex="-1">Q50: How does the frontend maintain high performance without a virtual DOM? <a class="header-anchor" href="#q50-how-does-the-frontend-maintain-high-performance-without-a-virtual-dom" aria-label="Permalink to &quot;Q50: How does the frontend maintain high performance without a virtual DOM?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The billing console in <code>frontend/src/app.js</code> updates the DOM surgically using direct element references (<code>document.getElementById()</code>). Because only changed text nodes and table rows are mutated, memory overhead is negligible and render times are &lt;16ms (60 FPS).&quot;</p><hr><h2 id="_7-extended-technical-questions-q51-–-q155" tabindex="-1">7. Extended Technical Questions (Q51 – Q155) <a class="header-anchor" href="#_7-extended-technical-questions-q51-–-q155" aria-label="Permalink to &quot;7. Extended Technical Questions (Q51 – Q155)&quot;">​</a></h2><h3 id="q51-what-is-the-structure-of-an-ingesteventpayload" tabindex="-1">Q51: What is the structure of an IngestEventPayload? <a class="header-anchor" href="#q51-what-is-the-structure-of-an-ingesteventpayload" aria-label="Permalink to &quot;Q51: What is the structure of an IngestEventPayload?&quot;">​</a></h3><p><strong>Answer</strong>: Fields: <code>tenant_id</code>, <code>customer_id</code>, <code>event_type</code>, <code>quantity</code>, <code>idempotency_key</code>, <code>timestamp</code>, <code>project_id</code>, <code>unit</code>, and <code>dimensions</code>.</p><h3 id="q52-what-is-the-default-currency-in-this-billing-engine" tabindex="-1">Q52: What is the default currency in this billing engine? <a class="header-anchor" href="#q52-what-is-the-default-currency-in-this-billing-engine" aria-label="Permalink to &quot;Q52: What is the default currency in this billing engine?&quot;">​</a></h3><p><strong>Answer</strong>: USD, represented in integer minor units (cents). Multi-currency support handles EUR, GBP, CAD, AUD, JPY, and SGD.</p><h3 id="q53-what-http-status-code-is-returned-when-an-event-is-rejected-due-to-invalid-schema" tabindex="-1">Q53: What HTTP status code is returned when an event is rejected due to invalid schema? <a class="header-anchor" href="#q53-what-http-status-code-is-returned-when-an-event-is-rejected-due-to-invalid-schema" aria-label="Permalink to &quot;Q53: What HTTP status code is returned when an event is rejected due to invalid schema?&quot;">​</a></h3><p><strong>Answer</strong>: 422 Unprocessable Entity.</p><h3 id="q54-what-http-status-code-is-returned-when-an-idempotency-key-is-replayed" tabindex="-1">Q54: What HTTP status code is returned when an idempotency key is replayed? <a class="header-anchor" href="#q54-what-http-status-code-is-returned-when-an-idempotency-key-is-replayed" aria-label="Permalink to &quot;Q54: What HTTP status code is returned when an idempotency key is replayed?&quot;">​</a></h3><p><strong>Answer</strong>: 200 OK with <code>status: &quot;DUPLICATE&quot;</code>.</p><h3 id="q55-what-http-status-code-is-returned-when-a-non-existent-invoice-id-is-requested" tabindex="-1">Q55: What HTTP status code is returned when a non-existent invoice ID is requested? <a class="header-anchor" href="#q55-what-http-status-code-is-returned-when-a-non-existent-invoice-id-is-requested" aria-label="Permalink to &quot;Q55: What HTTP status code is returned when a non-existent invoice ID is requested?&quot;">​</a></h3><p><strong>Answer</strong>: 404 Not Found.</p><h3 id="q56-can-a-finalized-invoice-have-line-items-added-to-it" tabindex="-1">Q56: Can a finalized invoice have line items added to it? <a class="header-anchor" href="#q56-can-a-finalized-invoice-have-line-items-added-to-it" aria-label="Permalink to &quot;Q56: Can a finalized invoice have line items added to it?&quot;">​</a></h3><p><strong>Answer</strong>: No, <code>invoicing/manager.py</code> verifies status is <code>DRAFT</code>. Finalized invoices raise a 400 Bad Request error.</p><h3 id="q57-how-is-an-invoice-voided" tabindex="-1">Q57: How is an invoice voided? <a class="header-anchor" href="#q57-how-is-an-invoice-voided" aria-label="Permalink to &quot;Q57: How is an invoice voided?&quot;">​</a></h3><p><strong>Answer</strong>: By updating status to <code>VOID</code> and posting a reversing double-entry ledger transaction crediting AR and debiting Bad Debt Expense.</p><h3 id="q58-what-is-the-formula-for-calculating-net-revenue-in-reporting-metrics-py" tabindex="-1">Q58: What is the formula for calculating net revenue in <code>reporting/metrics.py</code>? <a class="header-anchor" href="#q58-what-is-the-formula-for-calculating-net-revenue-in-reporting-metrics-py" aria-label="Permalink to &quot;Q58: What is the formula for calculating net revenue in `reporting/metrics.py`?&quot;">​</a></h3><p><strong>Answer</strong>: $\\text{Net Revenue} = \\text{Subtotal} - \\text{Discounts} + \\text{Tax} = \\text{Total Invoiced Amount}$.</p><h3 id="q59-what-is-the-difference-between-recompute-from-scratch-and-pre-aggregated-rollups" tabindex="-1">Q59: What is the difference between <code>recompute_from_scratch</code> and pre-aggregated rollups? <a class="header-anchor" href="#q59-what-is-the-difference-between-recompute-from-scratch-and-pre-aggregated-rollups" aria-label="Permalink to &quot;Q59: What is the difference between `recompute_from_scratch` and pre-aggregated rollups?&quot;">​</a></h3><p><strong>Answer</strong>: Rollups are pre-aggregated buckets for fast UI reads; <code>recompute_from_scratch</code> runs a direct SQL <code>SUM</code> over raw events for ground-truth audits.</p><h3 id="q60-how-does-the-system-handle-negative-usage-quantities" tabindex="-1">Q60: How does the system handle negative usage quantities? <a class="header-anchor" href="#q60-how-does-the-system-handle-negative-usage-quantities" aria-label="Permalink to &quot;Q60: How does the system handle negative usage quantities?&quot;">​</a></h3><p><strong>Answer</strong>: Rejected at two levels: Pydantic field validation in Python and <code>CheckConstraint(&#39;quantity &gt;= 0&#39;)</code> in SQL.</p><h3 id="q61-what-role-does-clock-py-play-in-testing" tabindex="-1">Q61: What role does <code>clock.py</code> play in testing? <a class="header-anchor" href="#q61-what-role-does-clock-py-play-in-testing" aria-label="Permalink to &quot;Q61: What role does `clock.py` play in testing?&quot;">​</a></h3><p><strong>Answer</strong>: It allows tests to control and fast-forward time to verify dunning schedules and period closes deterministically.</p><h3 id="q62-what-is-the-maximum-allowed-clock-drift-for-incoming-events" tabindex="-1">Q62: What is the maximum allowed clock drift for incoming events? <a class="header-anchor" href="#q62-what-is-the-maximum-allowed-clock-drift-for-incoming-events" aria-label="Permalink to &quot;Q62: What is the maximum allowed clock drift for incoming events?&quot;">​</a></h3><p><strong>Answer</strong>: Up to 90 days in the past and up to 1 hour into the future.</p><h3 id="q63-what-happens-if-an-event-s-timestamp-is-2-hours-in-the-future" tabindex="-1">Q63: What happens if an event&#39;s timestamp is 2 hours in the future? <a class="header-anchor" href="#q63-what-happens-if-an-event-s-timestamp-is-2-hours-in-the-future" aria-label="Permalink to &quot;Q63: What happens if an event&#39;s timestamp is 2 hours in the future?&quot;">​</a></h3><p><strong>Answer</strong>: Rejected with error code <code>TIMESTAMP_IN_FUTURE</code>.</p><h3 id="q64-what-is-the-purpose-of-the-ix-tenant-idem-index" tabindex="-1">Q64: What is the purpose of the <code>ix_tenant_idem</code> index? <a class="header-anchor" href="#q64-what-is-the-purpose-of-the-ix-tenant-idem-index" aria-label="Permalink to &quot;Q64: What is the purpose of the `ix_tenant_idem` index?&quot;">​</a></h3><p><strong>Answer</strong>: Enforces unique idempotency keys per tenant, ensuring $O(\\log N)$ deduplication speed.</p><h3 id="q65-why-are-financial-transactions-stored-in-integer-cents" tabindex="-1">Q65: Why are financial transactions stored in integer cents? <a class="header-anchor" href="#q65-why-are-financial-transactions-stored-in-integer-cents" aria-label="Permalink to &quot;Q65: Why are financial transactions stored in integer cents?&quot;">​</a></h3><p><strong>Answer</strong>: To eliminate binary floating-point representation errors and guarantee exact compliance with accounting standards.</p><h3 id="q66-what-is-the-rounding-mode-used-in-proration-math" tabindex="-1">Q66: What is the rounding mode used in proration math? <a class="header-anchor" href="#q66-what-is-the-rounding-mode-used-in-proration-math" aria-label="Permalink to &quot;Q66: What is the rounding mode used in proration math?&quot;">​</a></h3><p><strong>Answer</strong>: <code>ROUND_HALF_UP</code> (standard financial rounding to the nearest cent).</p><h3 id="q67-how-does-subscriptionlifecyclemanager-calculate-proration-for-mid-cycle-plan-upgrades" tabindex="-1">Q67: How does <code>SubscriptionLifecycleManager</code> calculate proration for mid-cycle plan upgrades? <a class="header-anchor" href="#q67-how-does-subscriptionlifecyclemanager-calculate-proration-for-mid-cycle-plan-upgrades" aria-label="Permalink to &quot;Q67: How does `SubscriptionLifecycleManager` calculate proration for mid-cycle plan upgrades?&quot;">​</a></h3><p><strong>Answer</strong>: By computing remaining seconds ratio, calculating unused old plan credit and new plan charge, and charging the net difference.</p><h3 id="q68-what-are-the-4-dunning-stages-in-payments-collections-py" tabindex="-1">Q68: What are the 4 dunning stages in <code>payments/collections.py</code>? <a class="header-anchor" href="#q68-what-are-the-4-dunning-stages-in-payments-collections-py" aria-label="Permalink to &quot;Q68: What are the 4 dunning stages in `payments/collections.py`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>ATTEMPT_1</code> (Day 0), <code>ATTEMPT_2</code> (Day 3), <code>ATTEMPT_3</code> (Day 7), and <code>FINAL_ESCALATION</code> (Day 14).</p><h3 id="q69-what-account-standings-exist-in-the-dunning-workflow" tabindex="-1">Q69: What account standings exist in the dunning workflow? <a class="header-anchor" href="#q69-what-account-standings-exist-in-the-dunning-workflow" aria-label="Permalink to &quot;Q69: What account standings exist in the dunning workflow?&quot;">​</a></h3><p><strong>Answer</strong>: <code>GOOD</code>, <code>PAST_DUE</code>, and <code>SUSPENDED</code>.</p><h3 id="q70-when-does-an-account-transition-to-suspended" tabindex="-1">Q70: When does an account transition to <code>SUSPENDED</code>? <a class="header-anchor" href="#q70-when-does-an-account-transition-to-suspended" aria-label="Permalink to &quot;Q70: When does an account transition to `SUSPENDED`?&quot;">​</a></h3><p><strong>Answer</strong>: When payment collection fails past the 14-day grace period threshold.</p><h3 id="q71-how-are-credit-card-numbers-handled-in-this-system" tabindex="-1">Q71: How are credit card numbers handled in this system? <a class="header-anchor" href="#q71-how-are-credit-card-numbers-handled-in-this-system" aria-label="Permalink to &quot;Q71: How are credit card numbers handled in this system?&quot;">​</a></h3><p><strong>Answer</strong>: Never stored in the database; the system operates strictly with payment gateway tokens (<code>gateway_ref</code>).</p><h3 id="q72-what-regex-pattern-is-used-to-detect-tax-ids-in-audit-logs" tabindex="-1">Q72: What regex pattern is used to detect tax IDs in audit logs? <a class="header-anchor" href="#q72-what-regex-pattern-is-used-to-detect-tax-ids-in-audit-logs" aria-label="Permalink to &quot;Q72: What regex pattern is used to detect tax IDs in audit logs?&quot;">​</a></h3><p><strong>Answer</strong>: <code>\\b\\d{2}-\\d{7}\\b</code> (EIN) and <code>\\b\\d{3}-\\d{2}-\\d{4}\\b</code> (SSN).</p><h3 id="q73-what-is-the-role-of-asyncsessionlocal-in-db-database-py" tabindex="-1">Q73: What is the role of <code>AsyncSessionLocal</code> in <code>db/database.py</code>? <a class="header-anchor" href="#q73-what-is-the-role-of-asyncsessionlocal-in-db-database-py" aria-label="Permalink to &quot;Q73: What is the role of `AsyncSessionLocal` in `db/database.py`?&quot;">​</a></h3><p><strong>Answer</strong>: Creates async database session instances bound to the async SQLAlchemy engine.</p><h3 id="q74-why-is-expire-on-commit-false-set-in-sessionmaker" tabindex="-1">Q74: Why is <code>expire_on_commit=False</code> set in sessionmaker? <a class="header-anchor" href="#q74-why-is-expire-on-commit-false-set-in-sessionmaker" aria-label="Permalink to &quot;Q74: Why is `expire_on_commit=False` set in sessionmaker?&quot;">​</a></h3><p><strong>Answer</strong>: Prevents SQLAlchemy from reloading model attributes after an async commit, avoiding lazy-loading errors.</p><h3 id="q75-how-does-the-system-ensure-gapless-sequential-invoice-numbers" tabindex="-1">Q75: How does the system ensure gapless sequential invoice numbers? <a class="header-anchor" href="#q75-how-does-the-system-ensure-gapless-sequential-invoice-numbers" aria-label="Permalink to &quot;Q75: How does the system ensure gapless sequential invoice numbers?&quot;">​</a></h3><p><strong>Answer</strong>: Uses <code>SELECT ... FOR UPDATE</code> on <code>invoice_sequences</code> to serialize counter increments per tenant and year.</p><h3 id="q76-what-format-do-invoice-numbers-follow" tabindex="-1">Q76: What format do invoice numbers follow? <a class="header-anchor" href="#q76-what-format-do-invoice-numbers-follow" aria-label="Permalink to &quot;Q76: What format do invoice numbers follow?&quot;">​</a></h3><p><strong>Answer</strong>: <code>INV-{YEAR}-{NUMBER:04d}</code> (e.g., <code>INV-2026-0001</code>).</p><h3 id="q77-what-roles-are-defined-in-security-auth-py" tabindex="-1">Q77: What roles are defined in <code>security/auth.py</code>? <a class="header-anchor" href="#q77-what-roles-are-defined-in-security-auth-py" aria-label="Permalink to &quot;Q77: What roles are defined in `security/auth.py`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>OWNER</code>, <code>FINANCE</code>, <code>VIEWER</code>, and <code>SERVICE</code>.</p><h3 id="q78-can-a-service-role-finalize-an-invoice" tabindex="-1">Q78: Can a <code>SERVICE</code> role finalize an invoice? <a class="header-anchor" href="#q78-can-a-service-role-finalize-an-invoice" aria-label="Permalink to &quot;Q78: Can a `SERVICE` role finalize an invoice?&quot;">​</a></h3><p><strong>Answer</strong>: No, <code>SERVICE</code> has permissions only for <code>usage:ingest</code> and <code>webhooks:process</code>.</p><h3 id="q79-what-happens-if-an-api-key-is-revoked" tabindex="-1">Q79: What happens if an API key is revoked? <a class="header-anchor" href="#q79-what-happens-if-an-api-key-is-revoked" aria-label="Permalink to &quot;Q79: What happens if an API key is revoked?&quot;">​</a></h3><p><strong>Answer</strong>: The database lookup checks <code>is_revoked == False</code>; revoked keys immediately return 401 Unauthorized.</p><h3 id="q80-how-are-raw-api-keys-generated" tabindex="-1">Q80: How are raw API keys generated? <a class="header-anchor" href="#q80-how-are-raw-api-keys-generated" aria-label="Permalink to &quot;Q80: How are raw API keys generated?&quot;">​</a></h3><p><strong>Answer</strong>: Using Python&#39;s <code>secrets.token_urlsafe(32)</code> prefixed with the role name.</p><h3 id="q81-what-is-the-primary-key-of-usage-events" tabindex="-1">Q81: What is the primary key of <code>usage_events</code>? <a class="header-anchor" href="#q81-what-is-the-primary-key-of-usage-events" aria-label="Permalink to &quot;Q81: What is the primary key of `usage_events`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>event_id</code> (64-character string).</p><h3 id="q82-what-is-the-primary-key-of-ledger-transactions" tabindex="-1">Q82: What is the primary key of <code>ledger_transactions</code>? <a class="header-anchor" href="#q82-what-is-the-primary-key-of-ledger-transactions" aria-label="Permalink to &quot;Q82: What is the primary key of `ledger_transactions`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>transaction_id</code> (64-character string).</p><h3 id="q83-what-is-the-foreign-key-relationship-between-ledger-entries-and-ledger-transactions" tabindex="-1">Q83: What is the foreign key relationship between <code>ledger_entries</code> and <code>ledger_transactions</code>? <a class="header-anchor" href="#q83-what-is-the-foreign-key-relationship-between-ledger-entries-and-ledger-transactions" aria-label="Permalink to &quot;Q83: What is the foreign key relationship between `ledger_entries` and `ledger_transactions`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>ledger_entries.transaction_id</code> references <code>ledger_transactions.transaction_id</code>.</p><h3 id="q84-what-database-check-constraint-exists-on-ledger-entries" tabindex="-1">Q84: What database check constraint exists on <code>ledger_entries</code>? <a class="header-anchor" href="#q84-what-database-check-constraint-exists-on-ledger-entries" aria-label="Permalink to &quot;Q84: What database check constraint exists on `ledger_entries`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>CheckConstraint(&#39;amount_cents &gt; 0&#39;)</code>.</p><h3 id="q85-what-database-check-constraint-exists-on-usage-events" tabindex="-1">Q85: What database check constraint exists on <code>usage_events</code>? <a class="header-anchor" href="#q85-what-database-check-constraint-exists-on-usage-events" aria-label="Permalink to &quot;Q85: What database check constraint exists on `usage_events`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>CheckConstraint(&#39;quantity &gt;= 0&#39;)</code>.</p><h3 id="q86-what-pricing-models-are-supported-in-rating-engine-py" tabindex="-1">Q86: What pricing models are supported in <code>rating/engine.py</code>? <a class="header-anchor" href="#q86-what-pricing-models-are-supported-in-rating-engine-py" aria-label="Permalink to &quot;Q86: What pricing models are supported in `rating/engine.py`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>FLAT_FEE</code>, <code>PER_UNIT</code>, <code>TIERED_VOLUME</code>, <code>GRADUATED_BRACKET</code>, and <code>OVERAGE</code>.</p><h3 id="q87-what-is-an-overage-pricing-model" tabindex="-1">Q87: What is an overage pricing model? <a class="header-anchor" href="#q87-what-is-an-overage-pricing-model" aria-label="Permalink to &quot;Q87: What is an overage pricing model?&quot;">​</a></h3><p><strong>Answer</strong>: A base fee includes a fixed quantity of units; any excess usage beyond included units is billed at an overage unit rate.</p><h3 id="q88-how-are-free-units-handled-in-rating" tabindex="-1">Q88: How are free units handled in rating? <a class="header-anchor" href="#q88-how-are-free-units-handled-in-rating" aria-label="Permalink to &quot;Q88: How are free units handled in rating?&quot;">​</a></h3><p><strong>Answer</strong>: Deducted from total quantity before evaluating billable brackets: <code>billable_qty = max(0, qty - free_units)</code>.</p><h3 id="q89-what-is-the-purpose-of-meteraggregationtype-in-models-meters-py" tabindex="-1">Q89: What is the purpose of <code>MeterAggregationType</code> in <code>models/meters.py</code>? <a class="header-anchor" href="#q89-what-is-the-purpose-of-meteraggregationtype-in-models-meters-py" aria-label="Permalink to &quot;Q89: What is the purpose of `MeterAggregationType` in `models/meters.py`?&quot;">​</a></h3><p><strong>Answer</strong>: Defines how raw events are rolled up into billable meter metrics: <code>SUM</code>, <code>COUNT</code>, <code>MAX</code>, or <code>LAST</code>.</p><h3 id="q90-how-does-the-billing-engine-handle-multiple-meters-under-a-single-subscription-plan" tabindex="-1">Q90: How does the billing engine handle multiple meters under a single subscription plan? <a class="header-anchor" href="#q90-how-does-the-billing-engine-handle-multiple-meters-under-a-single-subscription-plan" aria-label="Permalink to &quot;Q90: How does the billing engine handle multiple meters under a single subscription plan?&quot;">​</a></h3><p><strong>Answer</strong>: The price book catalog allows multiple <code>PriceBookEntry</code> records per <code>plan_id</code>, each mapped to a distinct <code>event_type</code>.</p><h3 id="q91-what-is-the-endpoint-to-calculate-real-time-pricing-without-writing-to-the-database" tabindex="-1">Q91: What is the endpoint to calculate real-time pricing without writing to the database? <a class="header-anchor" href="#q91-what-is-the-endpoint-to-calculate-real-time-pricing-without-writing-to-the-database" aria-label="Permalink to &quot;Q91: What is the endpoint to calculate real-time pricing without writing to the database?&quot;">​</a></h3><p><strong>Answer</strong>: <code>POST /v1/rating/calculate</code>.</p><h3 id="q92-what-is-the-endpoint-to-fetch-the-billing-dashboard-kpi-summary" tabindex="-1">Q92: What is the endpoint to fetch the Billing Dashboard KPI summary? <a class="header-anchor" href="#q92-what-is-the-endpoint-to-fetch-the-billing-dashboard-kpi-summary" aria-label="Permalink to &quot;Q92: What is the endpoint to fetch the Billing Dashboard KPI summary?&quot;">​</a></h3><p><strong>Answer</strong>: <code>GET /v1/dashboard/summary?tenant_id={tenant_id}</code>.</p><h3 id="q93-what-kpis-are-returned-by-the-dashboard-summary-endpoint" tabindex="-1">Q93: What KPIs are returned by the dashboard summary endpoint? <a class="header-anchor" href="#q93-what-kpis-are-returned-by-the-dashboard-summary-endpoint" aria-label="Permalink to &quot;Q93: What KPIs are returned by the dashboard summary endpoint?&quot;">​</a></h3><p><strong>Answer</strong>: <code>gross_revenue_cents</code>, <code>net_revenue_cents</code>, <code>mrr_cents</code>, <code>arr_cents</code>, <code>active_subscriptions</code>, and <code>unpaid_amount_cents</code>.</p><h3 id="q94-how-does-the-frontend-format-integer-cents-into-currency-display" tabindex="-1">Q94: How does the frontend format integer cents into currency display? <a class="header-anchor" href="#q94-how-does-the-frontend-format-integer-cents-into-currency-display" aria-label="Permalink to &quot;Q94: How does the frontend format integer cents into currency display?&quot;">​</a></h3><p><strong>Answer</strong>: Using <code>formatCents(cents)</code>: <code>((cents || 0) / 100).toFixed(2)</code> formatted with a <code>$</code> prefix.</p><h3 id="q95-what-css-styling-paradigm-is-used-in-frontend-src-index-css" tabindex="-1">Q95: What CSS styling paradigm is used in <code>frontend/src/index.css</code>? <a class="header-anchor" href="#q95-what-css-styling-paradigm-is-used-in-frontend-src-index-css" aria-label="Permalink to &quot;Q95: What CSS styling paradigm is used in `frontend/src/index.css`?&quot;">​</a></h3><p><strong>Answer</strong>: Pure Vanilla CSS custom properties (<code>--bg-black: #000000</code>, <code>--text-main: #f8fafc</code>) providing a responsive dark theme.</p><h3 id="q96-how-does-the-frontend-handle-backend-api-network-errors" tabindex="-1">Q96: How does the frontend handle backend API network errors? <a class="header-anchor" href="#q96-how-does-the-frontend-handle-backend-api-network-errors" aria-label="Permalink to &quot;Q96: How does the frontend handle backend API network errors?&quot;">​</a></h3><p><strong>Answer</strong>: Catches network exceptions in <code>try/catch</code> blocks and logs graceful warnings without freezing the UI.</p><h3 id="q97-what-happens-when-an-invoice-is-marked-void" tabindex="-1">Q97: What happens when an invoice is marked <code>VOID</code>? <a class="header-anchor" href="#q97-what-happens-when-an-invoice-is-marked-void" aria-label="Permalink to &quot;Q97: What happens when an invoice is marked `VOID`?&quot;">​</a></h3><p><strong>Answer</strong>: Its status is set to <code>VOID</code>, and a compensating double-entry ledger transaction is posted to reverse outstanding AR.</p><h3 id="q98-can-an-invoice-transition-from-finalized-back-to-draft" tabindex="-1">Q98: Can an invoice transition from <code>FINALIZED</code> back to <code>DRAFT</code>? <a class="header-anchor" href="#q98-can-an-invoice-transition-from-finalized-back-to-draft" aria-label="Permalink to &quot;Q98: Can an invoice transition from `FINALIZED` back to `DRAFT`?&quot;">​</a></h3><p><strong>Answer</strong>: No, state transitions are strictly one-way: <code>DRAFT -&gt; FINALIZED -&gt; PAID</code> or <code>VOID</code>.</p><h3 id="q99-what-is-the-purpose-of-usage-rollups-table" tabindex="-1">Q99: What is the purpose of <code>usage_rollups</code> table? <a class="header-anchor" href="#q99-what-is-the-purpose-of-usage-rollups-table" aria-label="Permalink to &quot;Q99: What is the purpose of `usage_rollups` table?&quot;">​</a></h3><p><strong>Answer</strong>: Stores pre-aggregated usage by hour or day to allow instant dashboard analytics without scanning billions of raw events.</p><h3 id="q100-what-index-optimizes-queries-against-usage-rollups" tabindex="-1">Q100: What index optimizes queries against <code>usage_rollups</code>? <a class="header-anchor" href="#q100-what-index-optimizes-queries-against-usage-rollups" aria-label="Permalink to &quot;Q100: What index optimizes queries against `usage_rollups`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>ix_rollup_lookup</code> on <code>(tenant_id, customer_id, event_type, granularity, bucket_start)</code>.</p><h3 id="q101-how-does-usageaggregator-prevent-overlapping-hourly-rollup-buckets" tabindex="-1">Q101: How does <code>UsageAggregator</code> prevent overlapping hourly rollup buckets? <a class="header-anchor" href="#q101-how-does-usageaggregator-prevent-overlapping-hourly-rollup-buckets" aria-label="Permalink to &quot;Q101: How does `UsageAggregator` prevent overlapping hourly rollup buckets?&quot;">​</a></h3><p><strong>Answer</strong>: By computing exact UTC bucket boundaries (<code>floor to start of hour</code>) and enforcing unique compound constraints.</p><h3 id="q102-how-does-the-system-authenticate-internal-microservices-vs-customer-ui-sessions" tabindex="-1">Q102: How does the system authenticate internal microservices vs customer UI sessions? <a class="header-anchor" href="#q102-how-does-the-system-authenticate-internal-microservices-vs-customer-ui-sessions" aria-label="Permalink to &quot;Q102: How does the system authenticate internal microservices vs customer UI sessions?&quot;">​</a></h3><p><strong>Answer</strong>: Both use API keys hashed via SHA-256; microservices are assigned the <code>SERVICE</code> role, while web consoles use <code>FINANCE</code> or <code>VIEWER</code> keys.</p><h3 id="q103-what-is-the-difference-between-an-event-timestamp-and-received-at" tabindex="-1">Q103: What is the difference between an event timestamp and <code>received_at</code>? <a class="header-anchor" href="#q103-what-is-the-difference-between-an-event-timestamp-and-received-at" aria-label="Permalink to &quot;Q103: What is the difference between an event timestamp and `received_at`?&quot;">​</a></h3><p><strong>Answer</strong>: <code>timestamp</code> is when the consumption occurred on the client device; <code>received_at</code> is when the server received the payload.</p><h3 id="q104-why-is-received-at-generated-server-side" tabindex="-1">Q104: Why is <code>received_at</code> generated server-side? <a class="header-anchor" href="#q104-why-is-received-at-generated-server-side" aria-label="Permalink to &quot;Q104: Why is `received_at` generated server-side?&quot;">​</a></h3><p><strong>Answer</strong>: To detect client clock drift and provide an immutable audit timestamp independent of client-controlled clocks.</p><h3 id="q105-what-is-the-maximum-number-of-events-permitted-in-a-single-batch-ingest-call" tabindex="-1">Q105: What is the maximum number of events permitted in a single batch ingest call? <a class="header-anchor" href="#q105-what-is-the-maximum-number-of-events-permitted-in-a-single-batch-ingest-call" aria-label="Permalink to &quot;Q105: What is the maximum number of events permitted in a single batch ingest call?&quot;">​</a></h3><p><strong>Answer</strong>: Up to 1,000 events per request payload.</p><h3 id="q106-what-happens-if-one-event-in-a-batch-payload-fails-schema-validation" tabindex="-1">Q106: What happens if one event in a batch payload fails schema validation? <a class="header-anchor" href="#q106-what-happens-if-one-event-in-a-batch-payload-fails-schema-validation" aria-label="Permalink to &quot;Q106: What happens if one event in a batch payload fails schema validation?&quot;">​</a></h3><p><strong>Answer</strong>: The pipeline rejects the invalid event with an error in the response array while successfully processing valid entries, or aborts the batch depending on atomic flag settings.</p><h3 id="q107-how-does-test-database-distributed-infrastructure-py-verify-partitioning" tabindex="-1">Q107: How does <code>test_database_distributed_infrastructure.py</code> verify partitioning? <a class="header-anchor" href="#q107-how-does-test-database-distributed-infrastructure-py-verify-partitioning" aria-label="Permalink to &quot;Q107: How does `test_database_distributed_infrastructure.py` verify partitioning?&quot;">​</a></h3><p><strong>Answer</strong>: By executing <code>EXPLAIN</code> queries against SQLite/PostgreSQL to verify partition pruning.</p><h3 id="q108-how-many-passing-automated-tests-exist-in-the-test-suite" tabindex="-1">Q108: How many passing automated tests exist in the test suite? <a class="header-anchor" href="#q108-how-many-passing-automated-tests-exist-in-the-test-suite" aria-label="Permalink to &quot;Q108: How many passing automated tests exist in the test suite?&quot;">​</a></h3><p><strong>Answer</strong>: 87 passing tests across 52 test files.</p><h3 id="q109-what-test-command-runs-the-complete-test-suite" tabindex="-1">Q109: What test command runs the complete test suite? <a class="header-anchor" href="#q109-what-test-command-runs-the-complete-test-suite" aria-label="Permalink to &quot;Q109: What test command runs the complete test suite?&quot;">​</a></h3><p><strong>Answer</strong>: <code>PYTHONPATH=backend/src pytest</code>.</p><h3 id="q110-how-does-test-graduated-pricing-py-verify-mathematical-accuracy" tabindex="-1">Q110: How does <code>test_graduated_pricing.py</code> verify mathematical accuracy? <a class="header-anchor" href="#q110-how-does-test-graduated-pricing-py-verify-mathematical-accuracy" aria-label="Permalink to &quot;Q110: How does `test_graduated_pricing.py` verify mathematical accuracy?&quot;">​</a></h3><p><strong>Answer</strong>: Compares rating output against golden hand-computed test matrices specified independently of the code.</p><h3 id="q111-what-is-the-purpose-of-pricetier-schema" tabindex="-1">Q111: What is the purpose of <code>PriceTier</code> schema? <a class="header-anchor" href="#q111-what-is-the-purpose-of-pricetier-schema" aria-label="Permalink to &quot;Q111: What is the purpose of `PriceTier` schema?&quot;">​</a></h3><p><strong>Answer</strong>: Models a single pricing bracket with <code>up_to</code> threshold, <code>unit_price_cents</code>, and optional tier <code>flat_fee_cents</code>.</p><h3 id="q112-how-does-the-rating-engine-represent-an-unbounded-top-tier" tabindex="-1">Q112: How does the rating engine represent an unbounded top tier? <a class="header-anchor" href="#q112-how-does-the-rating-engine-represent-an-unbounded-top-tier" aria-label="Permalink to &quot;Q112: How does the rating engine represent an unbounded top tier?&quot;">​</a></h3><p><strong>Answer</strong>: By setting <code>up_to = None</code>.</p><h3 id="q113-what-happens-if-an-empty-tier-list-is-passed-for-graduated-pricing" tabindex="-1">Q113: What happens if an empty tier list is passed for graduated pricing? <a class="header-anchor" href="#q113-what-happens-if-an-empty-tier-list-is-passed-for-graduated-pricing" aria-label="Permalink to &quot;Q113: What happens if an empty tier list is passed for graduated pricing?&quot;">​</a></h3><p><strong>Answer</strong>: <code>RatingEngine.rate_usage()</code> raises a <code>ValueError(&quot;Graduated pricing requires tiers configuration&quot;)</code>.</p><h3 id="q114-how-does-the-invoice-manager-compute-line-item-totals" tabindex="-1">Q114: How does the invoice manager compute line-item totals? <a class="header-anchor" href="#q114-how-does-the-invoice-manager-compute-line-item-totals" aria-label="Permalink to &quot;Q114: How does the invoice manager compute line-item totals?&quot;">​</a></h3><p><strong>Answer</strong>: <code>amount_cents = quantity * unit_price_cents</code>.</p><h3 id="q115-what-is-the-formula-for-invoice-total" tabindex="-1">Q115: What is the formula for invoice total? <a class="header-anchor" href="#q115-what-is-the-formula-for-invoice-total" aria-label="Permalink to &quot;Q115: What is the formula for invoice total?&quot;">​</a></h3><p><strong>Answer</strong>: <code>total_cents = subtotal_cents - discount_cents - credit_cents + tax_cents</code>.</p><h3 id="q116-can-total-cents-on-an-invoice-be-negative" tabindex="-1">Q116: Can <code>total_cents</code> on an invoice be negative? <a class="header-anchor" href="#q116-can-total-cents-on-an-invoice-be-negative" aria-label="Permalink to &quot;Q116: Can `total_cents` on an invoice be negative?&quot;">​</a></h3><p><strong>Answer</strong>: No, credits and discounts are clamped so the total cannot fall below zero.</p><h3 id="q117-what-accounts-are-involved-in-invoice-finalization" tabindex="-1">Q117: What accounts are involved in invoice finalization? <a class="header-anchor" href="#q117-what-accounts-are-involved-in-invoice-finalization" aria-label="Permalink to &quot;Q117: What accounts are involved in invoice finalization?&quot;">​</a></h3><p><strong>Answer</strong>: Debit: Accounts Receivable (<code>AR</code>), Credit: Revenue (<code>REV</code>).</p><h3 id="q118-what-accounts-are-involved-in-payment-capture" tabindex="-1">Q118: What accounts are involved in payment capture? <a class="header-anchor" href="#q118-what-accounts-are-involved-in-payment-capture" aria-label="Permalink to &quot;Q118: What accounts are involved in payment capture?&quot;">​</a></h3><p><strong>Answer</strong>: Debit: Cash (<code>CASH</code>), Credit: Accounts Receivable (<code>AR</code>).</p><h3 id="q119-what-accounts-are-involved-in-customer-refunds" tabindex="-1">Q119: What accounts are involved in customer refunds? <a class="header-anchor" href="#q119-what-accounts-are-involved-in-customer-refunds" aria-label="Permalink to &quot;Q119: What accounts are involved in customer refunds?&quot;">​</a></h3><p><strong>Answer</strong>: Debit: Revenue or Refund Expense (<code>REFUND</code>), Credit: Cash (<code>CASH</code>).</p><h3 id="q120-what-is-the-lifespan-context-manager-in-app-py" tabindex="-1">Q120: What is the lifespan context manager in <code>app.py</code>? <a class="header-anchor" href="#q120-what-is-the-lifespan-context-manager-in-app-py" aria-label="Permalink to &quot;Q120: What is the lifespan context manager in `app.py`?&quot;">​</a></h3><p><strong>Answer</strong>: An asynchronous context manager executing <code>init_db()</code> on application startup to ensure schema readiness.</p><h3 id="q121-how-are-cors-headers-configured-in-app-py" tabindex="-1">Q121: How are CORS headers configured in <code>app.py</code>? <a class="header-anchor" href="#q121-how-are-cors-headers-configured-in-app-py" aria-label="Permalink to &quot;Q121: How are CORS headers configured in `app.py`?&quot;">​</a></h3><p><strong>Answer</strong>: Using <code>CORSMiddleware</code> with configurable <code>allow_origins</code>, <code>allow_methods</code>, and <code>allow_headers</code>.</p><h3 id="q122-what-happens-when-get-health-is-queried" tabindex="-1">Q122: What happens when <code>GET /health</code> is queried? <a class="header-anchor" href="#q122-what-happens-when-get-health-is-queried" aria-label="Permalink to &quot;Q122: What happens when `GET /health` is queried?&quot;">​</a></h3><p><strong>Answer</strong>: The handler executes <code>SELECT 1</code> on the database session and returns <code>{ &quot;status&quot;: &quot;ok&quot;, &quot;service&quot;: &quot;19-usage-billing-engine&quot; }</code>.</p><h3 id="q123-what-does-an-ingestionstatus-rejected-response-indicate" tabindex="-1">Q123: What does an <code>IngestionStatus.REJECTED</code> response indicate? <a class="header-anchor" href="#q123-what-does-an-ingestionstatus-rejected-response-indicate" aria-label="Permalink to &quot;Q123: What does an `IngestionStatus.REJECTED` response indicate?&quot;">​</a></h3><p><strong>Answer</strong>: Payload failed validation (e.g. negative quantity or excessive timestamp drift); no database write occurred.</p><h3 id="q124-how-does-pricebookmanager-get-entries-for-plan-query-pricing-rules" tabindex="-1">Q124: How does <code>PriceBookManager.get_entries_for_plan</code> query pricing rules? <a class="header-anchor" href="#q124-how-does-pricebookmanager-get-entries-for-plan-query-pricing-rules" aria-label="Permalink to &quot;Q124: How does `PriceBookManager.get_entries_for_plan` query pricing rules?&quot;">​</a></h3><p><strong>Answer</strong>: Uses <code>select(PriceBookEntryRecord).where(tenant_id == ..., plan_id == ...)</code>.</p><h3 id="q125-what-is-annual-recurring-revenue-arr" tabindex="-1">Q125: What is Annual Recurring Revenue (ARR)? <a class="header-anchor" href="#q125-what-is-annual-recurring-revenue-arr" aria-label="Permalink to &quot;Q125: What is Annual Recurring Revenue (ARR)?&quot;">​</a></h3><p><strong>Answer</strong>: $\\text{MRR} \\times 12$.</p><h3 id="q126-what-is-average-revenue-per-user-arpu" tabindex="-1">Q126: What is Average Revenue Per User (ARPU)? <a class="header-anchor" href="#q126-what-is-average-revenue-per-user-arpu" aria-label="Permalink to &quot;Q126: What is Average Revenue Per User (ARPU)?&quot;">​</a></h3><p><strong>Answer</strong>: $\\text{Total MRR} / \\text{Active Subscriptions Count}$.</p><h3 id="q127-how-does-test-proration-hand-computed-verify-proration" tabindex="-1">Q127: How does <code>test_proration_hand_computed</code> verify proration? <a class="header-anchor" href="#q127-how-does-test-proration-hand-computed-verify-proration" aria-label="Permalink to &quot;Q127: How does `test_proration_hand_computed` verify proration?&quot;">​</a></h3><p><strong>Answer</strong>: Compares net proration cents against hand-calculated golden figures down to the exact integer cent.</p><h3 id="q128-what-is-the-difference-between-volume-tiered-and-flat-subscription-pricing" tabindex="-1">Q128: What is the difference between volume-tiered and flat subscription pricing? <a class="header-anchor" href="#q128-what-is-the-difference-between-volume-tiered-and-flat-subscription-pricing" aria-label="Permalink to &quot;Q128: What is the difference between volume-tiered and flat subscription pricing?&quot;">​</a></h3><p><strong>Answer</strong>: Volume pricing charges based on usage brackets; flat subscription pricing charges a fixed recurring fee regardless of usage.</p><h3 id="q129-what-is-the-purpose-of-paymentattemptrecord" tabindex="-1">Q129: What is the purpose of <code>PaymentAttemptRecord</code>? <a class="header-anchor" href="#q129-what-is-the-purpose-of-paymentattemptrecord" aria-label="Permalink to &quot;Q129: What is the purpose of `PaymentAttemptRecord`?&quot;">​</a></h3><p><strong>Answer</strong>: Stores every charge attempt with an attempt number, idempotency key, status, and gateway error code.</p><h3 id="q130-why-is-idempotency-key-indexed-on-payment-attempts" tabindex="-1">Q130: Why is <code>idempotency_key</code> indexed on <code>payment_attempts</code>? <a class="header-anchor" href="#q130-why-is-idempotency-key-indexed-on-payment-attempts" aria-label="Permalink to &quot;Q130: Why is `idempotency_key` indexed on `payment_attempts`?&quot;">​</a></h3><p><strong>Answer</strong>: To prevent parallel retry requests from submitting duplicate authorization charges to the gateway.</p><h3 id="q131-what-is-the-dunning-retry-schedule" tabindex="-1">Q131: What is the dunning retry schedule? <a class="header-anchor" href="#q131-what-is-the-dunning-retry-schedule" aria-label="Permalink to &quot;Q131: What is the dunning retry schedule?&quot;">​</a></h3><p><strong>Answer</strong>: Day 0 (Immediate), Day 3 (Retry 1), Day 7 (Retry 2), and Day 14 (Final Notice &amp; Suspension).</p><h3 id="q132-what-happens-when-an-account-standing-becomes-suspended" tabindex="-1">Q132: What happens when an account standing becomes <code>SUSPENDED</code>? <a class="header-anchor" href="#q132-what-happens-when-an-account-standing-becomes-suspended" aria-label="Permalink to &quot;Q132: What happens when an account standing becomes `SUSPENDED`?&quot;">​</a></h3><p><strong>Answer</strong>: Ingestion and API access are blocked until outstanding invoices are settled.</p><h3 id="q133-how-does-auditlogmanager-record-before-and-after-states" tabindex="-1">Q133: How does <code>AuditLogManager</code> record before and after states? <a class="header-anchor" href="#q133-how-does-auditlogmanager-record-before-and-after-states" aria-label="Permalink to &quot;Q133: How does `AuditLogManager` record before and after states?&quot;">​</a></h3><p><strong>Answer</strong>: By serializing model dictionaries to sanitized JSON strings in <code>before_state</code> and <code>after_state</code> columns.</p><h3 id="q134-how-does-the-system-handle-leap-years-in-invoice-numbering" tabindex="-1">Q134: How does the system handle leap years in invoice numbering? <a class="header-anchor" href="#q134-how-does-the-system-handle-leap-years-in-invoice-numbering" aria-label="Permalink to &quot;Q134: How does the system handle leap years in invoice numbering?&quot;">​</a></h3><p><strong>Answer</strong>: Sequence counters are keyed by <code>(tenant_id, year)</code> where <code>year</code> is extracted from UTC datetime (<code>dt.year</code>).</p><h3 id="q135-what-database-driver-is-used-for-sqlite-during-development" tabindex="-1">Q135: What database driver is used for SQLite during development? <a class="header-anchor" href="#q135-what-database-driver-is-used-for-sqlite-during-development" aria-label="Permalink to &quot;Q135: What database driver is used for SQLite during development?&quot;">​</a></h3><p><strong>Answer</strong>: <code>aiosqlite</code>.</p><h3 id="q136-what-database-driver-is-used-for-postgresql-in-production" tabindex="-1">Q136: What database driver is used for PostgreSQL in production? <a class="header-anchor" href="#q136-what-database-driver-is-used-for-postgresql-in-production" aria-label="Permalink to &quot;Q136: What database driver is used for PostgreSQL in production?&quot;">​</a></h3><p><strong>Answer</strong>: <code>asyncpg</code>.</p><h3 id="q137-how-does-the-engine-support-custom-usage-dimensions-like-region-and-endpoint" tabindex="-1">Q137: How does the engine support custom usage dimensions like <code>region</code> and <code>endpoint</code>? <a class="header-anchor" href="#q137-how-does-the-engine-support-custom-usage-dimensions-like-region-and-endpoint" aria-label="Permalink to &quot;Q137: How does the engine support custom usage dimensions like `region` and `endpoint`?&quot;">​</a></h3><p><strong>Answer</strong>: Dimensions are stored in a flexible <code>dimensions_json</code> column and indexed via composite tenant indices.</p><h3 id="q138-can-a-customer-have-multiple-active-subscriptions" tabindex="-1">Q138: Can a customer have multiple active subscriptions? <a class="header-anchor" href="#q138-can-a-customer-have-multiple-active-subscriptions" aria-label="Permalink to &quot;Q138: Can a customer have multiple active subscriptions?&quot;">​</a></h3><p><strong>Answer</strong>: Yes, subscriptions are mapped by unique <code>subscription_id</code> per customer.</p><h3 id="q139-what-is-the-purpose-of-planversionrecord-base-fee-cents" tabindex="-1">Q139: What is the purpose of <code>PlanVersionRecord.base_fee_cents</code>? <a class="header-anchor" href="#q139-what-is-the-purpose-of-planversionrecord-base-fee-cents" aria-label="Permalink to &quot;Q139: What is the purpose of `PlanVersionRecord.base_fee_cents`?&quot;">​</a></h3><p><strong>Answer</strong>: Defines the fixed recurring platform charge before metered usage is applied.</p><h3 id="q140-what-happens-if-a-payment-capture-fails" tabindex="-1">Q140: What happens if a payment capture fails? <a class="header-anchor" href="#q140-what-happens-if-a-payment-capture-fails" aria-label="Permalink to &quot;Q140: What happens if a payment capture fails?&quot;">​</a></h3><p><strong>Answer</strong>: Payment status is updated to <code>FAILED</code>, the attempt is logged, and the dunning workflow advances to the next retry stage.</p><h3 id="q141-what-is-the-role-of-vitepress-in-this-repository" tabindex="-1">Q141: What is the role of <code>vitepress</code> in this repository? <a class="header-anchor" href="#q141-what-is-the-role-of-vitepress-in-this-repository" aria-label="Permalink to &quot;Q141: What is the role of `vitepress` in this repository?&quot;">​</a></h3><p><strong>Answer</strong>: Generates the developer documentation website with pure-black dark theme and Mermaid diagram support.</p><h3 id="q142-how-does-withmermaid-integrate-with-vitepress" tabindex="-1">Q142: How does <code>withMermaid</code> integrate with VitePress? <a class="header-anchor" href="#q142-how-does-withmermaid-integrate-with-vitepress" aria-label="Permalink to &quot;Q142: How does `withMermaid` integrate with VitePress?&quot;">​</a></h3><p><strong>Answer</strong>: Wraps VitePress config to compile and render Markdown <code>mermaid</code> blocks into client-side SVG diagrams.</p><h3 id="q143-what-is-the-purpose-of-custom-css-in-vitepress" tabindex="-1">Q143: What is the purpose of <code>custom.css</code> in VitePress? <a class="header-anchor" href="#q143-what-is-the-purpose-of-custom-css-in-vitepress" aria-label="Permalink to &quot;Q143: What is the purpose of `custom.css` in VitePress?&quot;">​</a></h3><p><strong>Answer</strong>: Overrides VitePress default theme colors, forcing <code>--vp-c-bg: #000000</code> for pure black dark mode.</p><h3 id="q144-how-are-unit-conversions-verified-in-tests" tabindex="-1">Q144: How are unit conversions verified in tests? <a class="header-anchor" href="#q144-how-are-unit-conversions-verified-in-tests" aria-label="Permalink to &quot;Q144: How are unit conversions verified in tests?&quot;">​</a></h3><p><strong>Answer</strong>: In <code>test_usage_metering_core.py</code>, conversions between MB and GB or seconds and hours are asserted against float tolerances.</p><h3 id="q145-what-happens-when-a-tenant-ledger-is-reconciled" tabindex="-1">Q145: What happens when a tenant ledger is reconciled? <a class="header-anchor" href="#q145-what-happens-when-a-tenant-ledger-is-reconciled" aria-label="Permalink to &quot;Q145: What happens when a tenant ledger is reconciled?&quot;">​</a></h3><p><strong>Answer</strong>: <code>reconcile_tenant_ledger()</code> computes sum of all tenant debits and credits; returns <code>True</code> if difference is 0.</p><h3 id="q146-what-was-the-hardest-technical-decision-you-had-to-make" tabindex="-1">Q146: What was the hardest technical decision you had to make? <a class="header-anchor" href="#q146-what-was-the-hardest-technical-decision-you-had-to-make" aria-label="Permalink to &quot;Q146: What was the hardest technical decision you had to make?&quot;">​</a></h3><p><strong>Answer</strong>: Choosing between an event-sourced ledger vs a double-entry ledger. I chose double-entry because standard accounting and auditing require debit-credit balance sheets.</p><h3 id="q147-how-did-you-diagnose-the-sequence-number-race-condition" tabindex="-1">Q147: How did you diagnose the sequence number race condition? <a class="header-anchor" href="#q147-how-did-you-diagnose-the-sequence-number-race-condition" aria-label="Permalink to &quot;Q147: How did you diagnose the sequence number race condition?&quot;">​</a></h3><p><strong>Answer</strong>: By writing a concurrent test running 50 asyncio workers finalizing invoices simultaneously and catching unique constraint violations.</p><h3 id="q148-what-did-you-learn-about-python-s-decimal-module" tabindex="-1">Q148: What did you learn about Python&#39;s Decimal module? <a class="header-anchor" href="#q148-what-did-you-learn-about-python-s-decimal-module" aria-label="Permalink to &quot;Q148: What did you learn about Python&#39;s Decimal module?&quot;">​</a></h3><p><strong>Answer</strong>: That initializing <code>Decimal</code> with floats introduces precision artifacts (e.g. <code>Decimal(0.1)</code> vs <code>Decimal(&#39;0.1&#39;)</code>); strings must always be used.</p><h3 id="q149-how-do-you-prevent-memory-leaks-in-long-running-fastapi-processes" tabindex="-1">Q149: How do you prevent memory leaks in long-running FastAPI processes? <a class="header-anchor" href="#q149-how-do-you-prevent-memory-leaks-in-long-running-fastapi-processes" aria-label="Permalink to &quot;Q149: How do you prevent memory leaks in long-running FastAPI processes?&quot;">​</a></h3><p><strong>Answer</strong>: By scoping database sessions to individual request lifespans using FastAPI&#39;s <code>Depends(get_db)</code> and releasing connections immediately.</p><h3 id="q150-how-do-you-test-billing-features-without-waiting-30-days-for-cycle-close" tabindex="-1">Q150: How do you test billing features without waiting 30 days for cycle close? <a class="header-anchor" href="#q150-how-do-you-test-billing-features-without-waiting-30-days-for-cycle-close" aria-label="Permalink to &quot;Q150: How do you test billing features without waiting 30 days for cycle close?&quot;">​</a></h3><p><strong>Answer</strong>: By injecting a <code>ManualClock</code> simulator into the period and dunning managers, advancing time programmatically in tests.</p><h3 id="q151-what-metrics-would-you-set-up-in-prometheus-to-monitor-this-system" tabindex="-1">Q151: What metrics would you set up in Prometheus to monitor this system? <a class="header-anchor" href="#q151-what-metrics-would-you-set-up-in-prometheus-to-monitor-this-system" aria-label="Permalink to &quot;Q151: What metrics would you set up in Prometheus to monitor this system?&quot;">​</a></h3><p><strong>Answer</strong>: Ingestion rate (<code>events/sec</code>), rating duration percentiles (p95, p99), invoice finalization counts, and ledger imbalance alarms.</p><h3 id="q152-how-would-you-migrate-from-sqlite-to-postgresql-in-production" tabindex="-1">Q152: How would you migrate from SQLite to PostgreSQL in production? <a class="header-anchor" href="#q152-how-would-you-migrate-from-sqlite-to-postgresql-in-production" aria-label="Permalink to &quot;Q152: How would you migrate from SQLite to PostgreSQL in production?&quot;">​</a></h3><p><strong>Answer</strong>: SQLAlchemy&#39;s abstract ORM definitions make switching dialects seamless: only <code>DATABASE_URL</code> changes from <code>sqlite+aiosqlite</code> to <code>postgresql+asyncpg</code>.</p><h3 id="q153-how-does-the-system-handle-currency-conversion" tabindex="-1">Q153: How does the system handle currency conversion? <a class="header-anchor" href="#q153-how-does-the-system-handle-currency-conversion" aria-label="Permalink to &quot;Q153: How does the system handle currency conversion?&quot;">​</a></h3><p><strong>Answer</strong>: Invoices are generated in customer account base currency; multi-currency conversions are handled via external exchange rate tables before line-item generation.</p><h3 id="q154-what-is-the-role-of-pydantic-configdict-from-attributes-true" tabindex="-1">Q154: What is the role of <code>pydantic.ConfigDict(from_attributes=True)</code>? <a class="header-anchor" href="#q154-what-is-the-role-of-pydantic-configdict-from-attributes-true" aria-label="Permalink to &quot;Q154: What is the role of `pydantic.ConfigDict(from_attributes=True)`?&quot;">​</a></h3><p><strong>Answer</strong>: Enables Pydantic models to automatically serialize data directly from SQLAlchemy ORM records.</p><h3 id="q155-summarize-the-primary-technical-achievement-of-this-project" tabindex="-1">Q155: Summarize the primary technical achievement of this project. <a class="header-anchor" href="#q155-summarize-the-primary-technical-achievement-of-this-project" aria-label="Permalink to &quot;Q155: Summarize the primary technical achievement of this project.&quot;">​</a></h3><p><strong>Answer</strong>: Building a high-throughput, idempotent billing engine that combines sub-millisecond telemetry ingestion with mathematically exact integer rating and immutable double-entry accounting.&quot;</p>',242)])])}const f=i(r,[["render",d]]);export{m as __pageData,f as default};
